<?php require_once __DIR__.'/../config.php';admin_required();verify_csrf();$allowed=['Menunggu Konfirmasi','Dikonfirmasi','Sedang Dikerjakan','Selesai','Dibatalkan'];$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if($id>0&&in_array($status,$allowed,true)){db()->prepare("UPDATE orders SET status=? WHERE id=?")->execute([$status,$id]);}header('Location: pesanan.php?ok=1');exit;